import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ProfileData } from "../types";

const profileSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    username: { type: Type.STRING },
    name: { type: Type.STRING },
    category: { type: Type.STRING },
    bio: { type: Type.STRING },
    link: { type: Type.STRING },
    postsCount: { type: Type.STRING },
    followersCount: { type: Type.STRING },
    followingCount: { type: Type.STRING },
    highlightTitles: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "Generate 2-4 short highlight titles (e.g. 'Travel', 'OOTD')"
    },
  },
  required: ["username", "name", "category", "bio", "link", "postsCount", "followersCount", "followingCount", "highlightTitles"],
};

export const generateProfileData = async (prompt: string): Promise<Partial<ProfileData> | null> => {
  if (!process.env.API_KEY) {
    console.error("API Key not found");
    return null;
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Generate a realistic Instagram profile JSON object based on this description: "${prompt}". Make it look authentic.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: profileSchema,
      },
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      // Map the flat AI response to our nested structure where necessary
      return {
        ...data,
        isVerified: true, // Default to verified for cool factor
      };
    }
    return null;
  } catch (error) {
    console.error("Error generating profile:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';

interface EditableTextProps {
  value: string;
  onChange: (val: string) => void;
  className?: string;
  multiline?: boolean;
  placeholder?: string;
}

export const EditableText: React.FC<EditableTextProps> = ({ 
  value, 
  onChange, 
  className = "", 
  multiline = false,
  placeholder = "Edit..."
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [localValue, setLocalValue] = useState(value);
  const inputRef = useRef<HTMLElement>(null);

  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    onChange(localValue);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !multiline) {
      e.preventDefault();
      handleBlur();
    }
  };

  if (isEditing) {
    if (multiline) {
      return (
        <textarea
          // @ts-ignore
          ref={inputRef}
          value={localValue}
          onChange={(e) => setLocalValue(e.target.value)}
          onBlur={handleBlur}
          className={`bg-gray-800/50 text-white p-1 rounded outline-none resize-none w-full border border-blue-500 ${className}`}
          rows={3}
        />
      );
    }
    return (
      <input
        // @ts-ignore
        ref={inputRef}
        value={localValue}
        onChange={(e) => setLocalValue(e.target.value)}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        className={`bg-gray-800/50 text-white px-1 rounded outline-none min-w-[20px] border border-blue-500 ${className}`}
      />
    );
  }

  return (
    <span 
      onClick={() => setIsEditing(true)} 
      className={`cursor-pointer hover:bg-white/10 hover:rounded px-0.5 transition-colors whitespace-pre-wrap ${className} ${!localValue ? 'opacity-50 italic' : ''}`}
    >
      {localValue || placeholder}
    </span>
  );
};

import React, { useRef } from 'react';
import { Camera } from 'lucide-react';

interface EditableImageProps {
  src: string;
  onChange: (newSrc: string) => void;
  className?: string;
  alt?: string;
  rounded?: boolean;
}

export const EditableImage: React.FC<EditableImageProps> = ({ src, onChange, className = "", alt = "image", rounded = false }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onChange(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className={`relative group cursor-pointer overflow-hidden ${className} ${rounded ? 'rounded-full' : ''}`} onClick={handleClick}>
      <img 
        src={src} 
        alt={alt} 
        className={`w-full h-full object-cover ${rounded ? 'rounded-full' : ''}`} 
      />
      <div className={`absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity ${rounded ? 'rounded-full' : ''}`}>
        <Camera className="w-6 h-6 text-white" />
      </div>
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
        accept="image/*"
      />
    </div>
  );
};

