export default function App() {
  const [profile, setProfile] = useState<ProfileData>(INITIAL_PROFILE);
  const [activeTab, setActiveTab] = useState<'grid' | 'reels' | 'tagged'>('reels');
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showAiModal, setShowAiModal] = useState(false);

  // -- Handlers --

  const updateProfile = (key: keyof ProfileData, value: any) => {
    setProfile(prev => ({ ...prev, [key]: value }));
  };

  const updateHighlight = (id: string, key: keyof Highlight, value: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.map(h => h.id === id ? { ...h, [key]: value } : h)
    }));
  };

  const addHighlight = () => {
    const newId = Date.now().toString();
    setProfile(prev => ({
      ...prev,
      highlights: [
        ...prev.highlights,
        {
          id: newId,
          title: 'Highlight',
          imageUrl: `https://picsum.photos/seed/${newId}/100/100`
        }
      ]
    }));
  };

  const removeHighlight = (id: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.filter(h => h.id !== id)
    }));
  };

  const updatePost = (id: string, changes: Partial<Post>) => {
    setProfile(prev => ({
      ...prev,
      posts: prev.posts.map(p => p.id === id ? { ...p, ...changes } : p)
    }));
  };

  const updateReel = (id: string, changes: Partial<Reel>) => {
    setProfile(prev => ({
      ...prev,
      reels: prev.reels.map(r => (r.id === id ? { ...r, ...changes } : r)),
    }));
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    try {
      const generatedData = await generateProfileData(prompt);
      if (generatedData) {
        setProfile(prev => ({
           ...prev,
           ...generatedData,
           // Keep images unless we want to complicate things by fetching new ones, 
           // for now we just update text fields mostly
           highlights: prev.highlights.map((h, i) => ({
             ...h,
             // @ts-ignore
             title: generatedData.highlightTitles?.[i] || h.title
           }))
        }));
        setShowAiModal(false);
      }
    } catch (e) {
      alert("Failed to generate profile. Check API Key or try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="w-full min-h-screen bg-black flex justify-center items-start pt-0 md:pt-10 pb-10">

      {/* --- Main Phone Container --- */}
