import React, { useState } from 'react';
import { 
  ChevronLeft, 
  MoreHorizontal, 
  BadgeCheck, 
  Grid,
  Clapperboard,
  Pin,
  Play,
  Wand2,
  RefreshCw,
  Plus,
  X
} from 'lucide-react';
import { INITIAL_PROFILE, ProfileData, Highlight, Reel, Post } from './types';
