);

const TaggedIcon = ({ className }: { className?: string }) => (
   <svg aria-label="Tagged" className={className} fill="currentColor" height="24" role="img" viewBox="0 0 24 24" width="24">
    <path d="M10.201 3.797 12 1.997l1.799 1.8a1.59 1.59 0 0 0 1.124.465h5.259A1.818 1.818 0 0 1 22 6.08v14.104a1.818 1.818 0 0 1-1.818 1.818H3.818A1.818 1.818 0 0 1 2 20.184V6.08a1.818 1.818 0 0 1 1.818-1.818h5.26a1.59 1.59 0 0 0 1.123-.465Z" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
    <path d="M18.598 22.002V21.4a3.949 3.949 0 0 0-3.948-3.949H9.495A3.949 3.949 0 0 0 5.546 21.4v.603" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
    <circle cx="12.072" cy="11.075" fill="none" r="3.556" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></circle>
  </svg>
);

export default function App() {
  const [profile, setProfile] = useState<ProfileData>(INITIAL_PROFILE);
  const [activeTab, setActiveTab] = useState<'grid' | 'reels' | 'tagged'>('reels');
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showAiModal, setShowAiModal] = useState(false);

  // -- Handlers --

  const updateProfile = (key: keyof ProfileData, value: any) => {
    setProfile(prev => ({ ...prev, [key]: value }));
  };

  const updateHighlight = (id: string, key: keyof Highlight, value: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.map(h => h.id === id ? { ...h, [key]: value } : h)
    }));
  };

  const addHighlight = () => {
    const newId = Date.now().toString();
    setProfile(prev => ({
      ...prev,
      highlights: [
        ...prev.highlights,
        {
          id: newId,
          title: 'Highlight',
          imageUrl: `https://picsum.photos/seed/${newId}/100/100`
        }
      ]
    }));
  };

  const removeHighlight = (id: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.filter(h => h.id !== id)
    }));
  };

  const updatePost = (id: string, changes: Partial<Post>) => {
    setProfile(prev => ({
      ...prev,
      posts: prev.posts.map(p => p.id === id ? { ...p, ...changes } : p)
    }));
  };

  const updateReel = (id: string, changes: Partial<Reel>) => {
    setProfile(prev => ({
      ...prev,
      reels: prev.reels.map(r => (r.id === id ? { ...r, ...changes } : r)),
    }));
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    try {
      const generatedData = await generateProfileData(prompt);
      if (generatedData) {
        setProfile(prev => ({
           ...prev,
           ...generatedData,
           // Keep images unless we want to complicate things by fetching new ones, 
           // for now we just update text fields mostly
           highlights: prev.highlights.map((h, i) => ({
             ...h,
             // @ts-ignore
             title: generatedData.highlightTitles?.[i] || h.title
           }))
        }));
        setShowAiModal(false);
      }
    } catch (e) {
      alert("Failed to generate profile. Check API Key or try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="w-full min-h-screen bg-black flex justify-center items-start pt-0 md:pt-10 pb-10">

      {/* --- Main Phone Container --- */}
      <div className="relative w-full md:w-[410px] md:h-[880px] bg-black md:border md:border-gray-800 md:rounded-[40px] overflow-hidden flex flex-col text-white shadow-2xl">

        {/* --- Header --- */}
        <div className="h-12 px-4 flex justify-between items-center bg-black sticky top-0 z-20 pt-4">
          <div className="flex items-center gap-6">
            <ChevronLeft className="w-7 h-7 cursor-pointer" />
            <div className="flex items-center gap-1 font-bold text-lg">
              <EditableText 
                value={profile.username} 
                onChange={(v) => updateProfile('username', v)} 
              />
              {profile.isVerified && (
                <BadgeCheck className="w-5 h-5 text-blue-500 fill-blue-500 text-black cursor-pointer" onClick={() => updateProfile('isVerified', false)} />
              )}
              {!profile.isVerified && (
                 <div className="w-4 h-4 rounded-full border border-gray-600 opacity-30 cursor-pointer" onClick={() => updateProfile('isVerified', true)} title="Toggle Verification"></div>
              )}
            </div>
          </div>
          <div className="flex gap-4">
             <MoreHorizontal className="w-6 h-6" />
          </div>
        </div>

        {/* --- Scrollable Content --- */}
        <div className="flex-1 scrollbar-hide overflow-y-auto no-scrollbar">

          {/* --- Padded Profile Info Container --- */}
          <div className="px-4 pt-6 pb-2">
            <div className="flex items-center justify-between mb-4">
               {/* Profile Pic */}
               <div className="relative">
                  <div className="w-[88px] h-[88px] rounded-full bg-gradient-to-tr from-[#f9ce34] via-[#ee2a7b] to-[#6228d7] p-[2.5px]">
                     <div className="w-full h-full rounded-full bg-black p-[2.5px]">
                       <EditableImage 
                          src={profile.profilePic} 
                          onChange={(v) => updateProfile('profilePic', v)} 
                          rounded 
                          className="w-full h-full"
                       />
                     </div>
                  </div>
               </div>

               {/* Name and Stats */}
               <div className="flex flex-col flex-1 ml-4">
                  <EditableText 
                    className="text-base" 
                    value={profile.name} 
                    onChange={(v) => updateProfile('name', v)} 
                    placeholder="Name"
                  />
                  <div className="flex flex-1 justify-between items-center mt-2">
                     <div className="flex flex-col items-start">
                       <EditableText className="font-bold text-lg leading-tight" value={profile.postsCount} onChange={(v) => updateProfile('postsCount', v)} />
                       <span className="text-sm">posts</span>
                     </div>
                     <div className="flex flex-col items-start">
                       <EditableText className="font-bold text-lg leading-tight" value={profile.followersCount} onChange={(v) => updateProfile('followersCount', v)} />
                       <span className="text-sm">followers</span>
                     </div>
                     <div className="flex flex-col items-start">
                       <EditableText className="font-bold text-lg leading-tight" value={profile.followingCount} onChange={(v) => updateProfile('followingCount', v)} />
                       <span className="text-sm">following</span>
                     </div>
                   </div>
               </div>
            </div>

            {/* Bio Section */}
            <div className="px-1 text-sm">
               <EditableText 
                 className="text-gray-400 block my-0.5" 
                 value={profile.category} 
                 onChange={(v) => updateProfile('category', v)} 
                 placeholder="Category"
               />
               <EditableText 
                 className="block whitespace-pre-wrap leading-tight" 
                 value={profile.bio} 
                 onChange={(v) => updateProfile('bio', v)} 
                 multiline
                 placeholder="Write your bio..."
               />
               <div className="flex items-center gap-1 mt-1 text-ig_link font-medium">
                 <svg aria-label="Link icon" fill="currentColor" height="12" role="img" viewBox="0 0 24 24" width="12"><path d="m9.364 10.776-.328-.329A6.027 6.027 0 0 0 3.65 9.07a6.028 6.028 0 0 0-2.096 9.682l3.652 3.651a6.026 6.026 0 0 0 8.524 0 6.026 6.026 0 0 0 0-8.523l-.329-.328a1 1 0 1 0-1.414 1.414l.329.328a4.026 4.026 0 0 1 0 5.695 4.026 4.026 0 0 1-5.695 0L2.97 17.337a4.029 4.029 0 0 1 1.4-6.47 4.026 4.026 0 0 1 4.294.943l.329.329a1 1 0 1 0 1.414-1.414Zm12.182-8.322a6.027 6.027 0 0 0-8.524 0l-.329.329a1 1 0 1 0 1.414 1.414l.329-.328a4.026 4.026 0 0 1 5.695 0 4.026 4.026 0 0 1 0 5.695l-3.652 3.651a4.028 4.028 0 0 1-5.694 0 4.029 4.029 0 0 1-1.4-6.47 1 1 0 1 0-1.572 1.144 6.029 6.029 0 0 0 2.096 9.683 6.026 6.026 0 0 0 8.524 0l3.651-3.651a6.027 6.027 0 0 0 0-8.524ZM13.842 8.745a1 1 0 0 0-1.414 1.414l2.828 2.829a1 1 0 1 0 1.414-1.414Z"></path></svg>
                 <EditableText 
                   value={profile.link} 
                   onChange={(v) => updateProfile('link', v)} 
                 />
               </div>
               {/* Followed by info could go here */}
            </div>

            {/* Buttons */}
            <div className="flex gap-1.5 mt-4 text-sm font-semibold">
              <button className="flex-1 bg-ig_blue text-white py-1.5 rounded-lg active:opacity-80">Follow</button>
              <button className="flex-1 bg-ig_gray text-white py-1.5 rounded-lg active:opacity-80">Message</button>
              <button className="flex-1 bg-ig_gray text-white py-1.5 rounded-lg active:opacity-80">Email</button>
              <button className="bg-ig_gray text-white p-1.5 rounded-lg active:opacity-80 px-2">
                 <svg aria-label="Down chevron icon" fill="currentColor" height="16" role="img" viewBox="0 0 24 24" width="16"><path d="M21 17.502a.997.997 0 0 1-.707-.293L12 8.913l-8.293 8.296a1 1 0 1 1-1.414-1.414l9-9.004a1 1 0 0 1 1.414 0l9 9.004A1 1 0 0 1 21 17.502Z"></path></svg>
              </button>
            </div>

            {/* Highlights */}
            <div className="flex gap-4 mt-6 overflow-x-auto no-scrollbar pb-2 px-1">
               {profile.highlights.map(hl => (
                  <div key={hl.id} className="relative flex flex-col items-center gap-1 min-w-[70px] group">
                     <button 
                       onClick={() => removeHighlight(hl.id)}
                       className="absolute -top-1 -right-0 z-10 bg-gray-900 rounded-full text-gray-400 hover:text-white opacity-0 group-hover:opacity-100 transition-opacity"
                       title="Remove Highlight"
                     >
                       <X size={14} className="bg-gray-800 rounded-full border border-gray-700" />
                     </button>
                     <div className="w-[64px] h-[64px] rounded-full bg-gray-800 border border-gray-700 p-[1px]">
                       <div className="w-full h-full rounded-full overflow-hidden bg-black">
                          <EditableImage 
                             src={hl.imageUrl} 
                             onChange={(v) => updateHighlight(hl.id, 'imageUrl', v)} 
                             className="w-full h-full opacity-90 hover:opacity-100"
                          />
                       </div>
                     </div>
                     <EditableText 
                       className="text-xs text-center truncate w-full" 
                       value={hl.title} 
                       onChange={(v) => updateHighlight(hl.id, 'title', v)}
                     />
                  </div>
               ))}
               {/* Add Highlight Placeholder */}
               <div 
                  className="flex flex-col items-center gap-1 min-w-[70px] cursor-pointer group"
                  onClick={addHighlight}
               >
                 <div className="w-[64px] h-[64px] rounded-full border border-gray-700 flex items-center justify-center group-hover:bg-white/5 transition-colors">
                    <Plus strokeWidth={1} size={32} className="text-white" />
                 </div>
                 <span className="text-xs">New</span>
               </div>
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="flex justify-around border-t border-ig_separator mt-2">
             <div 
                className={`flex-1 py-2.5 flex justify-center ${activeTab === 'grid' ? 'border-b border-white text-white' : 'text-gray-500'}`}
             >
                <Grid size={24} />
             </div>
             <div 
                className={`flex-1 py-2.5 flex justify-center cursor-pointer ${activeTab === 'reels' ? 'border-b border-white text-white' : 'text-gray-500'}`}
                onClick={() => setActiveTab('reels')}
             >
                <ReelsIcon className={activeTab === 'reels' ? 'text-white' : 'text-gray-500'} />
             </div>
             <div 
                className={`flex-1 py-2.5 flex justify-center ${activeTab === 'tagged' ? 'border-b border-white text-white' : 'text-gray-500'}`}
             >
                <TaggedIcon className={activeTab === 'tagged' ? 'text-white' : 'text-gray-500'} />
             </div>
          </div>

          {/* Grid Content */}
          {activeTab === 'grid' && (
            <div className="grid grid-cols-3 gap-0.5 pb-4">
               {profile.posts.map(post => (
                 <div key={post.id} className="relative aspect-square bg-gray-800 group overflow-hidden">
                    <EditableImage 
                       src={post.imageUrl} 
                       onChange={(v) => updatePost(post.id, { imageUrl: v })}
                       className="w-full h-full hover:scale-105 transition-transform duration-300" 
                    />
                    <div className="absolute top-2 right-2 flex flex-col gap-1 pointer-events-none">
                      {post.isPinned && <Pin size={16} className="fill-white text-white rotate-45 drop-shadow-md" />}
                      {post.isVideo && <Play size={16} className="fill-white text-white drop-shadow-md" />}
                    </div>
                    {/* Hover controls for individual posts */}
                    <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-2 transition-opacity">
                       <button 
                         onClick={(e) => { e.stopPropagation(); updatePost(post.id, { isPinned: !post.isPinned }); }}
                         className={`p-1.5 rounded-full ${post.isPinned ? 'bg-white text-black' : 'bg-black/50 text-white'}`}
                         title="Toggle Pin"
                       >
                         <Pin size={14} />
                       </button>
                       <button 
                         onClick={(e) => { e.stopPropagation(); updatePost(post.id, { isVideo: !post.isVideo }); }}
                         className={`p-1.5 rounded-full ${post.isVideo ? 'bg-white text-black' : 'bg-black/50 text-white'}`}
                         title="Toggle Video Icon"
                       >
                         <Clapperboard size={14} />
                       </button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'reels' && (
            <div className="grid grid-cols-3 gap-0.5 pb-4">
              {profile.reels.map((reel) => (
                <div key={reel.id} className="relative aspect-[3/4] bg-gray-800 group">
                  <EditableImage
                    src={reel.imageUrl}
                    onChange={(v) => updateReel(reel.id, { imageUrl: v })}
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute bottom-2 left-2 flex items-center gap-1 text-white text-xs font-bold drop-shadow-md">
                    <Play size={14} fill="currentColor" className="pointer-events-none" />
                    <EditableText
                      value={reel.views}
                      onChange={(v) => updateReel(reel.id, { views: v })}
                      className="!p-0 !bg-transparent hover:!bg-black/30"
                    />
                  </div>
                </div>
              ))}
            </div>
          )}

           {activeTab === 'tagged' && (
             <div className="flex flex-col items-center justify-center py-20 text-gray-400">
               <div className="w-16 h-16 rounded-full border-2 border-gray-600 flex items-center justify-center mb-4">
                 <TaggedIcon className="w-8 h-8" />
               </div>
               <h3 className="font-bold text-xl text-white">Photos of you</h3>
               <p className="text-center text-sm px-10 mt-2">
                 When people tag you in photos, they'll appear here.
               </p>
             </div>
           )}
        </div>
      </div>

      {/* --- Floating Tools (Desktop side panel) --- */}
      <div className="hidden md:flex fixed right-8 top-10 flex-col gap-4 bg-gray-900 p-4 rounded-xl border border-gray-700 w-64 shadow-xl">
        <h2 className="text-xl font-bold mb-2 flex items-center gap-2">
          <Wand2 className="w-5 h-5 text-blue-400" /> 
          Creator Tools
        </h2>

        <div className="bg-gray-800 p-3 rounded-lg border border-gray-700">
           <label className="text-xs text-gray-400 font-bold uppercase mb-2 block">AI Profile Generator</label>
           <textarea 
             className="w-full bg-black/50 text-sm text-white p-2 rounded mb-2 h-20 resize-none outline-none border border-transparent focus:border-blue-500"
             placeholder="e.g. A cyberpunk artist from Tokyo who loves ramen..."
             value={prompt}
             onChange={(e) => setPrompt(e.target.value)}
           />
           <button 
             onClick={handleGenerate}
             disabled={isGenerating || !prompt}
             className="w-full bg-blue-600 hover:bg-blue-500 text-white py-1.5 rounded flex items-center justify-center gap-2 transition-colors disabled:opacity-50"
           >
             {isGenerating ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />}
             {isGenerating ? 'Generating...' : 'Magic Fill'}
           </button>
           <p className="text-[10px] text-gray-500 mt-2">
             Note: Requires valid Gemini API Key in env.
           </p>
        </div>

        <div className="text-xs text-gray-400">
          <p>Click any text or image on the phone preview to edit it directly.</p>
        </div>
      </div>

       {/* Mobile AI Modal */}
       {showAiModal && (
        <div className="fixed inset-0 z-[60] bg-black/80 flex items-center justify-center p-4">
          <div className="bg-gray-900 w-full max-w-sm p-6 rounded-2xl border border-gray-700">
            <h3 className="text-lg font-bold mb-4">Generate Profile</h3>
             <textarea 
               className="w-full bg-black text-white p-3 rounded-lg mb-4 h-32 border border-gray-700"
               placeholder="Describe the persona..."
               value={prompt}
               onChange={(e) => setPrompt(e.target.value)}
             />
             <div className="flex gap-3">
               <button onClick={() => setShowAiModal(false)} className="flex-1 py-2 bg-gray-800 rounded-lg">Cancel</button>
               <button onClick={handleGenerate} disabled={isGenerating} className="flex-1 py-2 bg-blue-600 rounded-lg text-white flex justify-center items-center gap-2">
                  {isGenerating ? '...' : 'Generate'}
               </button>
             </div>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState } from 'react';
import { 
  ChevronLeft, 
  MoreHorizontal, 
  Grid,
  Clapperboard,
  Pin,
  Play,
  Wand2,
  RefreshCw,
  Plus,
  X
} from 'lucide-react';
import { INITIAL_PROFILE, ProfileData, Highlight, Reel, Post } from './types';
import { EditableText } from './components/EditableText';
import { EditableImage } from './components/EditableImage';
import { generateProfileData } from './services/geminiService';

// Custom icons to match IG exactly where Lucide differs slightly
