            posts: document.getElementById('posts-grid'),
            reels: document.getElementById('reels-grid'),
            tagged: document.getElementById('tagged-content'),
        };
        const tabToContentKey = { grid: 'posts', reels: 'reels', tagged: 'tagged' };

        function switchTab(activeTabKey) {
            Object.keys(tabs).forEach(key => {
                const tabEl = tabs[key];
                const contentEl = content[tabToContentKey[key]];

                if (key === activeTabKey) {
                    tabEl.classList.add('border-white', 'text-white');
                    tabEl.classList.remove('text-ig_secondary');
                    if (contentEl) contentEl.classList.remove('hidden');
