                    tabEl.classList.add('text-ig_secondary');
                    if (contentEl) contentEl.classList.add('hidden');
                }
            });
        }

        Object.keys(tabs).forEach(key => {
            tabs[key].addEventListener('click', () => switchTab(key));
        });
