// Helper to escape HTML special characters
function escapeHtml(unsafe: string): string {
    if (!unsafe) return '';
    return unsafe
         .replace(/&/g, "&amp;")
         .replace(/</g, "&lt;")
         .replace(/>/g, "&gt;")
         .replace(/"/g, "&quot;")
         .replace(/'/g, "&#039;");
}

function ensureUrlProtocol(url: string): string {
    if (!url) return '#';
    return (!url.startsWith('http://') && !url.startsWith('https://')) ? `https://${url}` : url;
}

// Helper to fetch an image URL and convert it to a Base64 string
async function imageUrlToBase64(url: string): Promise<string> {
  if (!url || url.startsWith('data:image')) {
    return url;
  }
  try {
    // FIX: Switched to a more reliable CORS proxy to prevent "Failed to fetch" errors.
    const proxyUrl = 'https://api.allorigins.win/raw?url=';
    const response = await fetch(`${proxyUrl}${encodeURIComponent(url)}`);
    if (!response.ok) throw new Error(`Network response was not ok for ${url}`);
    const blob = await response.blob();
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.error(`Failed to convert image URL to Base64: ${url}`, error);
    // Fallback to a placeholder on error
    return 'https://via.placeholder.com/400';
  }
}

