import React, { useState, useRef, useEffect } from 'react';
import { 
  ChevronLeft, 
  MoreHorizontal, 
  Grid,
  Clapperboard,
  Pin,
  Play,
  RefreshCw,
  Plus,
  X,
  Download
} from 'lucide-react';
import { INITIAL_PROFILE, ProfileData, Highlight, Reel, Post } from './types';
import { EditableText } from './components/EditableText';
import { EditableImage } from './components/EditableImage';
import { generateExportHtml } from './services/exportService';


// Custom icons to match IG exactly where Lucide differs slightly
const ReelsIcon = ({ className }: { className?: string }) => (
  <svg aria-label="Reels" className={className} fill="currentColor" height="24" role="img" viewBox="0 0 24 24" width="24">
    <line fill="none" stroke="currentColor" strokeLinejoin="round" strokeWidth="2" x1="2.049" x2="21.95" y1="7.002" y2="7.002"></line>
    <line fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" x1="13.504" x2="16.362" y1="2.001" y2="7.002"></line>
    <line fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" x1="7.207" x2="10.002" y1="2.11" y2="7.002"></line>
    <path d="M2 12.001v3.449c0 2.849.698 4.006 1.606 4.945.94.908 2.098 1.607 4.946 1.607h6.896c2.848 0 4.006-.699 4.946-1.607.908-.939 1.606-2.096 1.606-4.945V8.552c0-2.848-.698-4.006-1.606-4.945C19.454 2.699 18.296 2 15.448 2H8.552c-2.848 0-4.006.699-4.946 1.607C2.698 4.546 2 5.704 2 8.552Z" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
  </svg>
);

const TaggedIcon = ({ className }: { className?: string }) => (
   <svg aria-label="Tagged" className={className} fill="currentColor" height="24" role="img" viewBox="0 0 24 24" width="24">
    <path d="M10.201 3.797 12 1.997l1.799 1.8a1.59 1.59 0 0 0 1.124.465h5.259A1.818 1.818 0 0 1 22 6.08v14.104a1.818 1.818 0 0 1-1.818 1.818H3.818A1.818 1.818 0 0 1 2 20.184V6.08a1.818 1.818 0 0 1 1.818-1.818h5.26a1.59 1.59 0 0 0 1.123-.465Z" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
    <path d="M18.598 22.002V21.4a3.949 3.949 0 0 0-3.948-3.949H9.495A3.949 3.949 0 0 0 5.546 21.4v.603" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
    <circle cx="12.072" cy="11.075" fill="none" r="3.556" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></circle>
  </svg>
);

const VerificationIcon = (props: React.ComponentProps<'svg'>) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" {...props}>
      <path stroke="none" d="M0 0h24v24H0z" fill="none"/>
      <path d="M12.01 2.011a3.2 3.2 0 0 1 2.113 .797l.154 .145l.698 .698a1.2 1.2 0 0 0 .71 .341l.135 .008h1a3.2 3.2 0 0 1 3.195 3.018l.005 .182v1c0 .27 .092 .533 .258 .743l.09 .1l.697 .698a3.2 3.2 0 0 1 .147 4.382l-.145 .154l-.698 .698a1.2 1.2 0 0 0 -.341 .71l-.008 .135v1a3.2 3.2 0 0 1 -3.018 3.195l-.182 .005h-1a1.2 1.2 0 0 0 -.743 .258l-.1 .09l-.698 .697a3.2 3.2 0 0 1 -4.382 .147l-.154 -.145l-.698 -.698a1.2 1.2 0 0 0 -.71 -.341l-.135 -.008h-1a3.2 3.2 0 0 1 -3.195 -3.018l-.005 -.182v-1a1.2 1.2 0 0 0 -.258 -.743l-.09 -.1l-.697 -.698a3.2 3.2 0 0 1 -.147 -4.382l.145 -.154l.698 -.698a1.2 1.2 0 0 0 .341 -.71l.008 -.135v-1l.005 -.182a3.2 3.2 0 0 1 3.013 -3.013l.182 -.005h1a1.2 1.2 0 0 0 .743 -.258l.1 -.09l.698 -.697a3.2 3.2 0 0 1 2.269 -.944zm3.697 7.282a1 1 0 0 0 -1.414 0l-3.293 3.292l-1.293 -1.292l-.094 -.083a1 1 0 0 0 -1.32 1.497l2 2l.094 .083a1 1 0 0 0 1.32 -.083l4 -4l.083 -.094a1 1 0 0 0 -.083 -1.32z" />
  </svg>
);

export default function App() {
  const [profile, setProfile] = useState<ProfileData>(INITIAL_PROFILE);
  const [activeTab, setActiveTab] = useState<'grid' | 'reels' | 'tagged'>('reels');
  const [isExporting, setIsExporting] = useState(false);
  const [isEditingLink, setIsEditingLink] = useState(false);
  const linkEditorRef = useRef<HTMLDivElement>(null);

  // -- Handlers --

  const updateProfile = (key: keyof ProfileData, value: any) => {
    setProfile(prev => ({ ...prev, [key]: value }));
  };

  const updateHighlight = (id: string, key: keyof Highlight, value: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.map(h => h.id === id ? { ...h, [key]: value } : h)
    }));
  };

  const addHighlight = () => {
    const newId = Date.now().toString();
    setProfile(prev => ({
      ...prev,
      highlights: [
        ...prev.highlights,
        {
          id: newId,
          title: 'Highlight',
          imageUrl: `https://picsum.photos/seed/${newId}/100/100`
        }
      ]
    }));
  };

  const removeHighlight = (id: string) => {
    setProfile(prev => ({
      ...prev,
      highlights: prev.highlights.filter(h => h.id !== id)
    }));
  };

  const updatePost = (id: string, changes: Partial<Post>) => {
    setProfile(prev => ({
      ...prev,
      posts: prev.posts.map(p => p.id === id ? { ...p, ...changes } : p)
    }));
  };

  const updateReel = (id: string, changes: Partial<Reel>) => {
    setProfile(prev => ({
      ...prev,
      reels: prev.reels.map(r => (r.id === id ? { ...r, ...changes } : r)),
    }));
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
        const htmlContent = await generateExportHtml(profile);
        const blob = new Blob([htmlContent], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${profile.username}-profile.html`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    } catch (error) {
        console.error("Failed to export profile:", error);
        alert("An error occurred while exporting the profile. See console for details.");
    } finally {
        setIsExporting(false);
    }
  };

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
        if (linkEditorRef.current && !linkEditorRef.current.contains(event.target as Node)) {
            setIsEditingLink(false);
        }
    }
    if (isEditingLink) {
        document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
        document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isEditingLink, linkEditorRef]);


  return (
    <div className="w-full min-h-screen bg-black flex justify-center items-start pt-0 md:pt-10 pb-10">

      {/* --- Main Phone Container --- */}
      <div className="relative w-full md:w-[410px] md:h-[880px] bg-black md:border md:border-gray-800 md:rounded-[40px] overflow-hidden flex flex-col text-white shadow-2xl">

        {/* --- Header --- */}
        <div className="h-12 px-4 flex justify-between items-center bg-black sticky top-0 z-20 pt-4">
          <div className="flex items-center gap-6">
            <ChevronLeft className="w-7 h-7 cursor-pointer" />
            <div className="flex items-center gap-1 font-bold text-lg">
              <EditableText 
                value={profile.username} 
                onChange={(v) => updateProfile('username', v)} 
              />
              {profile.isVerified && (
                <VerificationIcon className="w-5 h-5 text-blue-500 cursor-pointer" onClick={() => updateProfile('isVerified', false)} />
              )}
              {!profile.isVerified && (
                 <div className="w-4 h-4 rounded-full border border-gray-600 opacity-30 cursor-pointer" onClick={() => updateProfile('isVerified', true)} title="Toggle Verification"></div>
              )}
            </div>
          </div>
          <div className="flex gap-4">
             <MoreHorizontal className="w-6 h-6" />
          </div>
        </div>

        {/* --- Scrollable Content --- */}
        <div className="flex-1 scrollbar-hide overflow-y-auto no-scrollbar">

          {/* --- Padded Profile Info Container --- */}
          <div className="px-4 pt-6 pb-2">
            <div className="flex items-center justify-between mb-4">
               {/* Profile Pic */}
               <div className="relative">
                  <div className="w-[88px] h-[88px] rounded-full bg-gradient-to-tr from-[#f9ce34] via-[#ee2a7b] to-[#6228d7] p-[2.5px]">
