                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"></path></svg>
                <span>${escapeHtml(reel.views)}</span>
            </div>
        </a>
    `).join('');

    return `
